Definition CEM_SCOPED_LOCK_STACK : Z := 32.

Definition cem_scoped_lock_post (ra sp gp tp s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (L M lo : Z) (j3 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a2 a3 a4 a5 m' j7,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (L, L + 16); (M + 8, M + 48)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' L [C8 (wz M); CB 1 [b8 1]; CB 7 j7]
    /\ rw_cells usegs m' (M + 48) [C4 (wz 0); CB 1 [b8 1]; CB 3 j3]
    /\ PMutex m' (M + 8) EBUSY.

Definition cem_scoped_lock_stmt : Prop :=
  forall (L M lo : Z) (j3 jl : list byte) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  rw_cells usegs m L [CB 16 jl] -> L mod 8 = 0 -> (L + 16 <= lo \/ bv_unsigned sp <= L) -> L + 16 <= 2^64 ->
  (* [comment removed for export] *)
  rw_cells usegs m (M + 48) [C4 (wz 0); CB 1 [b8 1]; CB 3 j3] -> PMutex m (M + 8) 0 -> 0 < M -> M + 56 <= hceil ->
  (L + 16 <= M \/ M + 56 <= L) ->
  stk usegs m lo (bv_unsigned sp) -> lo + CEM_SCOPED_LOCK_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  (* [comment removed for export] *) M mod 8 = 0 ->
  mem_inv usegs m ->
  evt usegs (cem_scoped_lock_post ra sp gp tp s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc L M lo j3 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz L) (wz M) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_CEM_SCOPED_LOCK) fc None m (seg_rom usegs)).
