Definition P_UB_CEM_LOCK_DTOR : Z := 0x321f4.
Definition CEM_LOCK_DTOR_STACK : Z := 16.

Definition cem_lock_dtor_post (ra sp gp tp s0 s1 a0 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp).

Definition cem_lock_dtor_stmt : Prop :=
  forall (L lo : Z) (mw : word) (j7 : list byte) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  rw_cells usegs m L [C8 mw; CB 1 [b8 0]; CB 7 j7] -> (L + 16 <= lo \/ bv_unsigned sp <= L) ->
  stk usegs m lo (bv_unsigned sp) -> lo + CEM_LOCK_DTOR_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (cem_lock_dtor_post ra sp gp tp s0 s1 (wz L) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz L) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_UB_CEM_LOCK_DTOR) fc None m (seg_rom usegs)).

