  /\ rw_cells usegs m (s + 48) [CB 2 [b8 0; b8 0]; CB 6 j50]
  /\ rw_cells usegs m (s + 56) [CB 8 jm]
  /\ PMutex m (s + 64) (sch_lk S)
  /\ rw_cells usegs m (s + 104) [C4 (wz 0); CB 1 [b8 1]; CB 3 j109]
  /\ rw_cells usegs m (s + 112) [CB 8 je]
  /\ PCond m (s + 120) CLOCK_MONOTONIC
  /\ rw_cells usegs m (s + 168)
       [C8 (wz 0); C8 (wz 0); C8 (wz P_SCHED_GET_DEFAULT_TASK); C8 (wz 0); C8 (wz 0); C4 (wz 0); CB 4 jt;
        CB 3 [b8 1; b8 (sch_stopped S); b8 (sch_shutdown S)]; CB 5 j219; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max); C8 (wz 0)]
  /\ rw_cells usegs m (s + 272) (CookieCells j7)
  /\ sv_vptr (sch_hdr S) = VP_SCHED /\ sv_destroy (sch_hdr S) = P_DESTROY_ALLOC_SCHED
  /\ (sch_stopped S = 0 \/ sch_stopped S = 1) /\ (sch_shutdown S = 0 \/ sch_shutdown S = 1).
