Definition SCHED_DTOR_STACK : Z := 48 + OPQUEUE_DTOR_STACK.   (* [comment removed for export] *)

Definition sched_dtor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (s lo : Z) (S : schv) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a2 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (s, s + 8)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ Scheduler LB m' s S.

Definition sched_dtor_stmt : Prop :=
  forall (s lo : Z) (LB : list block) (S : schv)
    ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  Scheduler LB m s S -> 0 < s -> s + NEWSZ_SCH <= hceil ->
  stk usegs m lo (bv_unsigned sp) -> lo + SCHED_DTOR_STACK <= bv_unsigned sp -> hceil <= lo ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (sched_dtor_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F fc LB s lo S m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz s) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SCHED_DTOR) fc None m (seg_rom usegs)).

