  Definition destroy_alloc_sched_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (sb ioc allocb regb schedb lo B : Z) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun cf => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (p : bptr),
      cfg_ms cf = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                     F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model cf) /\ hs_MPRES H mo (cfg_model cf)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ In (p, sb, NEWSZ_SCH) LB /\ hs_RHEAP H s' (hs_lb_remove H p LB) m'
      /\ AllocImpl (hs_lb_remove H p LB) m' allocb /\ XStatics m'
      /\ rw_cells usegs m' ioc (IoCtxCells allocb regb schedb)
      /\ xpres LB (bv_unsigned sp) [(sb, sb + NEWSZ_SCH)] m m'.

  Definition destroy_alloc_sched_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (sb ioc allocb regb schedb lo B : Z) (S : schv) (errv : word),
      a0 = Z_to_bv 64 sb ->
      Scheduler LB m sb S -> sv_owner (sch_hdr S) = ioc ->
      rw_cells usegs m ioc (IoCtxCells allocb regb schedb) -> bv_unsigned sp <= ioc ->
      ioc mod 8 = 0 ->                                                                  (* [comment removed for export] *)
      AllocImpl LB m allocb -> XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - DALL_STACK ->
